import { useEffect, useState } from 'react';
import { KeyRound, Plus, ShieldCheck, UserCog, UserRound, Users as UsersIcon } from 'lucide-react';

import { useAuth } from '../context/AuthContext.jsx';
import { useApiResource } from '../hooks/useApiResource.js';
import { INTERNAL_ROLES, ROLES } from '../lib/constants.js';
import { describeError } from '../lib/errors.js';
import { formatRelative } from '../lib/format.js';
import { usersApi, warehousesApi } from '../services/endpoints.js';
import { Badge } from '../components/ui/Badge.jsx';
import { Button } from '../components/ui/Button.jsx';
import { Card, CardToolbar } from '../components/ui/Card.jsx';
import { Dialog } from '../components/ui/Dialog.jsx';
import { Alert, EmptyState, ErrorState, TableSkeleton } from '../components/ui/Feedback.jsx';
import { Field, Input, Select } from '../components/ui/Input.jsx';
import { Pagination } from '../components/ui/Pagination.jsx';
import { Table, TBody, TD, TH, THead, TR } from '../components/ui/Table.jsx';
import { useToast } from '../components/ui/Toast.jsx';

const ROLE_TONE = {
  [ROLES.ADMIN]: 'destructive',
  [ROLES.MANAGER]: 'primary',
  [ROLES.STAFF]: 'info',
  [ROLES.CLIENT]: 'default',
};

const EMPTY_FORM = { name: '', email: '', password: '', role: ROLES.STAFF };

export function Users() {
  const { user: currentUser } = useAuth();
  const toast = useToast();

  const [page, setPage] = useState(1);
  const users = useApiResource(() => usersApi.list({ page, limit: 20 }), [page]);
  const warehouses = useApiResource(() => warehousesApi.list({ limit: 100 }), []);

  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState(EMPTY_FORM);
  const [formError, setFormError] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const [editing, setEditing] = useState(null);
  const [editForm, setEditForm] = useState({ name: '', role: ROLES.STAFF, is_active: true });
  const [editError, setEditError] = useState(null);

  const [accessFor, setAccessFor] = useState(null);
  const [selected, setSelected] = useState([]);
  const [accessError, setAccessError] = useState(null);

  const rows = users.data ?? [];
  const meta = users.meta ?? { page, limit: 20, total: 0 };
  const warehouseList = warehouses.data ?? [];

  useEffect(() => {
    if (accessFor) {
      setSelected((accessFor.warehouse_ids ?? []).map(String));
      setAccessError(null);
    }
  }, [accessFor]);

  async function handleCreate(event) {
    event.preventDefault();
    setSubmitting(true);
    setFormError(null);

    try {
      const created = await usersApi.create({
        name: form.name.trim(),
        email: form.email.trim(),
        password: form.password,
        role: form.role,
      });
      toast.success('User created', `${created.data?.name ?? form.name} can now sign in.`);
      setCreating(false);
      setForm(EMPTY_FORM);
      users.reload();
    } catch (caught) {
      setFormError(caught);
    } finally {
      setSubmitting(false);
    }
  }

  async function handleUpdate(event) {
    event.preventDefault();
    setSubmitting(true);
    setEditError(null);

    try {
      const result = await usersApi.update(editing.id, {
        name: editForm.name.trim(),
        role: editForm.role,
        // Only send is_active when it changed, so a rename never silently
        // revokes the user's sessions.
        ...(editForm.is_active !== editing.is_active ? { is_active: editForm.is_active } : {}),
      });

      toast.success(
        'User updated',
        result.data?.sessions_revoked
          ? 'Their existing sessions were revoked immediately.'
          : `${editForm.name.trim()} has been saved.`,
      );
      setEditing(null);
      users.reload();
      if (editing.id === currentUser?.id) {
        // An administrator who changed their own role must see the new state.
        window.location.reload();
      }
    } catch (caught) {
      setEditError(caught);
    } finally {
      setSubmitting(false);
    }
  }

  async function handleAccess(event) {
    event.preventDefault();
    setSubmitting(true);
    setAccessError(null);

    const before = new Set((accessFor.warehouse_ids ?? []).map(String));
    const after = new Set(selected);

    try {
      await usersApi.setWarehouseAccess(accessFor.id, {
        grant: [...after].filter((id) => !before.has(id)).map(Number),
        revoke: [...before].filter((id) => !after.has(id)).map(Number),
      });
      toast.success('Access updated', `${accessFor.name} now has ${selected.length} warehouse(s).`);
      setAccessFor(null);
      users.reload();
    } catch (caught) {
      setAccessError(caught);
    } finally {
      setSubmitting(false);
    }
  }

  async function toggleActive(target) {
    try {
      const result = await usersApi.update(target.id, { is_active: !target.is_active });
      toast.success(
        target.is_active ? 'User deactivated' : 'User reactivated',
        result.data?.sessions_revoked
          ? 'Any session they had open has been revoked.'
          : `${target.name} can sign in again.`,
      );
      users.reload();
    } catch (caught) {
      toast.error('Could not change the account', describeError(caught));
    }
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-base font-semibold tracking-tight">Users</h2>
          <p className="text-xs text-muted-foreground">
            {meta.total} account{meta.total === 1 ? '' : 's'}. Only administrators can change roles or
            warehouse access.
          </p>
        </div>
        <Button onClick={() => { setForm(EMPTY_FORM); setFormError(null); setCreating(true); }}>
          <Plus className="h-4 w-4" aria-hidden="true" />
          Add user
        </Button>
      </div>

      <Card>
        <CardToolbar>
          <p className="text-2xs text-muted-foreground">
            A Manager is scoped to the warehouses you grant; a Client sees only their own orders.
          </p>
        </CardToolbar>

        {users.error ? (
          <ErrorState error={users.error} onRetry={users.reload} />
        ) : users.loading ? (
          <TableSkeleton rows={8} columns={5} />
        ) : rows.length === 0 ? (
          <EmptyState icon={UsersIcon} title="No users" description="Create the first account." />
        ) : (
          <>
            <Table>
              <THead>
                <TR>
                  <TH>User</TH>
                  <TH>Role</TH>
                  <TH>Status</TH>
                  <TH>Warehouses</TH>
                  <TH className="text-right">Actions</TH>
                </TR>
              </THead>
              <TBody>
                {rows.map((row) => {
                  const isSelf = row.id === currentUser?.id;
                  const granted = (row.warehouse_ids ?? [])
                    .map((id) => warehouseList.find((warehouse) => warehouse.id === id))
                    .filter(Boolean);

                  return (
                    <TR key={row.id}>
                      <TD>
                        <div className="flex items-center gap-2.5">
                          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary/15 text-2xs font-semibold text-primary">
                            {row.name.slice(0, 2).toUpperCase()}
                          </span>
                          <span className="flex min-w-0 flex-col">
                            <span className="truncate text-xs font-medium">
                              {row.name}
                              {isSelf ? <span className="ml-1.5 text-2xs text-muted-foreground">(you)</span> : null}
                            </span>
                            <span className="truncate text-2xs text-muted-foreground">{row.email}</span>
                          </span>
                        </div>
                      </TD>
                      <TD>
                        <Badge tone={ROLE_TONE[row.role] ?? 'default'}>
                          <ShieldCheck className="h-3 w-3" aria-hidden="true" />
                          {row.role}
                        </Badge>
                      </TD>
                      <TD>
                        {row.is_active ? (
                          <Badge tone="success">Active</Badge>
                        ) : (
                          <Badge tone="outline">Disabled</Badge>
                        )}
                      </TD>
                      <TD>
                        {row.role === ROLES.ADMIN ? (
                          <span className="text-2xs text-muted-foreground">Every warehouse</span>
                        ) : row.role === ROLES.CLIENT ? (
                          <span className="text-2xs text-muted-foreground">Not applicable</span>
                        ) : granted.length === 0 ? (
                          <span className="text-2xs text-warning">None — sees no stock</span>
                        ) : (
                          <span className="flex flex-wrap gap-1">
                            {granted.map((warehouse) => (
                              <span
                                key={warehouse.id}
                                className="rounded border border-border px-1.5 py-0.5 font-mono text-2xs text-muted-foreground"
                              >
                                {warehouse.code}
                              </span>
                            ))}
                          </span>
                        )}
                      </TD>
                      <TD className="text-right">
                        <div className="flex items-center justify-end gap-1">
                          {INTERNAL_ROLES.includes(row.role) ? (
                            <Button variant="ghost" size="sm" onClick={() => setAccessFor(row)}>
                              <KeyRound className="h-3.5 w-3.5" aria-hidden="true" />
                              Access
                            </Button>
                          ) : null}
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setEditForm({ name: row.name, role: row.role, is_active: row.is_active });
                              setEditError(null);
                              setEditing(row);
                            }}
                          >
                            <UserCog className="h-3.5 w-3.5" aria-hidden="true" />
                            Edit
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            className={row.is_active ? 'text-destructive' : ''}
                            onClick={() => toggleActive(row)}
                            disabled={isSelf && row.is_active}
                            title={isSelf && row.is_active ? 'You cannot deactivate your own account' : undefined}
                          >
                            {row.is_active ? 'Deactivate' : 'Reactivate'}
                          </Button>
                        </div>
                      </TD>
                    </TR>
                  );
                })}
              </TBody>
            </Table>

            <Pagination
              page={meta.page ?? page}
              limit={meta.limit ?? 20}
              total={meta.total ?? 0}
              onPageChange={setPage}
            />
          </>
        )}
      </Card>

      {/* Create */}
      <Dialog
        open={creating}
        onClose={() => setCreating(false)}
        title="Add user"
        description="Registration through the sign-up page always creates a Client; staff accounts are created here."
        footer={
          <>
            <Button variant="outline" onClick={() => setCreating(false)}>
              Cancel
            </Button>
            <Button type="submit" form="user-form" loading={submitting}>
              Create user
            </Button>
          </>
        }
      >
        {formError ? (
          <div className="mb-4">
            <Alert tone="destructive" title="Could not create the user">
              {describeError(formError)}
            </Alert>
          </div>
        ) : null}

        <form id="user-form" className="flex flex-col gap-4" onSubmit={handleCreate}>
          <Field label="Full name" required error={formError?.fieldErrors?.name}>
            {(props) => (
              <Input
                {...props}
                value={form.name}
                onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))}
                placeholder="Ama Mensah"
                required
              />
            )}
          </Field>

          <Field label="Email" required error={formError?.fieldErrors?.email}>
            {(props) => (
              <Input
                {...props}
                type="email"
                autoComplete="off"
                value={form.email}
                onChange={(event) => setForm((current) => ({ ...current, email: event.target.value }))}
                placeholder="ama@stockpulse.dev"
                required
              />
            )}
          </Field>

          <Field
            label="Temporary password"
            required
            hint="At least 12 characters. Share it over a channel you trust."
            error={formError?.fieldErrors?.password}
          >
            {(props) => (
              <Input
                {...props}
                type="password"
                autoComplete="new-password"
                value={form.password}
                onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))}
                required
              />
            )}
          </Field>

          <Field label="Role" required hint="Warehouse access is granted after the account exists.">
            {(props) => (
              <Select
                {...props}
                value={form.role}
                onChange={(event) => setForm((current) => ({ ...current, role: event.target.value }))}
              >
                {Object.values(ROLES).map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </Select>
            )}
          </Field>
        </form>
      </Dialog>

      {/* Edit */}
      <Dialog
        open={Boolean(editing)}
        onClose={() => setEditing(null)}
        title={editing ? `Edit ${editing.name}` : 'Edit user'}
        description="Changing a role or disabling an account revokes the sessions that user already has open."
        footer={
          <>
            <Button variant="outline" onClick={() => setEditing(null)}>
              Cancel
            </Button>
            <Button type="submit" form="user-edit-form" loading={submitting}>
              Save changes
            </Button>
          </>
        }
      >
        {editError ? (
          <div className="mb-4">
            <Alert tone="destructive" title="Could not save">
              {describeError(editError)}
            </Alert>
          </div>
        ) : null}

        <form id="user-edit-form" className="flex flex-col gap-4" onSubmit={handleUpdate}>
          <Field label="Full name" required>
            {(props) => (
              <Input
                {...props}
                value={editForm.name}
                onChange={(event) => setEditForm((current) => ({ ...current, name: event.target.value }))}
                required
              />
            )}
          </Field>

          <Field label="Role" hint="The last active administrator cannot be demoted.">
            {(props) => (
              <Select
                {...props}
                value={editForm.role}
                onChange={(event) => setEditForm((current) => ({ ...current, role: event.target.value }))}
              >
                {Object.values(ROLES).map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </Select>
            )}
          </Field>

          <Field label="Status">
            {(props) => (
              <Select
                {...props}
                value={editForm.is_active ? 'active' : 'disabled'}
                onChange={(event) =>
                  setEditForm((current) => ({ ...current, is_active: event.target.value === 'active' }))
                }
              >
                <option value="active">Active — can sign in</option>
                <option value="disabled">Disabled — sessions revoked</option>
              </Select>
            )}
          </Field>

          <p className="flex items-start gap-1.5 text-2xs text-muted-foreground">
            <UserRound className="mt-0.5 h-3 w-3 shrink-0" aria-hidden="true" />
            {editing ? `Created ${formatRelative(editing.created_at)}` : null}
          </p>
        </form>
      </Dialog>

      {/* Warehouse access */}
      <Dialog
        open={Boolean(accessFor)}
        onClose={() => setAccessFor(null)}
        title={accessFor ? `Warehouse access — ${accessFor.name}` : 'Warehouse access'}
        description="Only the ticked warehouses appear in this user's inventory, orders and analytics."
        footer={
          <>
            <Button variant="outline" onClick={() => setAccessFor(null)}>
              Cancel
            </Button>
            <Button type="submit" form="access-form" loading={submitting}>
              Save access
            </Button>
          </>
        }
      >
        {accessError ? (
          <div className="mb-4">
            <Alert tone="destructive" title="Could not update access">
              {describeError(accessError)}
            </Alert>
          </div>
        ) : null}

        <form id="access-form" className="flex flex-col gap-2" onSubmit={handleAccess}>
          {warehouseList.length === 0 ? (
            <p className="text-xs text-muted-foreground">No warehouses exist yet.</p>
          ) : (
            warehouseList.map((warehouse) => {
              const id = String(warehouse.id);
              const checked = selected.includes(id);
              return (
                <label
                  key={warehouse.id}
                  className="flex cursor-pointer items-center justify-between gap-3 rounded-md border border-border px-3 py-2 transition-colors hover:bg-accent/40"
                >
                  <span className="flex min-w-0 flex-col">
                    <span className="truncate text-xs font-medium">{warehouse.name}</span>
                    <span className="font-mono text-2xs text-muted-foreground">
                      {warehouse.code}
                      {warehouse.manager ? ` · ${warehouse.manager.name}` : ''}
                    </span>
                  </span>
                  <input
                    type="checkbox"
                    className="h-4 w-4 accent-[hsl(var(--primary))]"
                    checked={checked}
                    onChange={(event) =>
                      setSelected((current) =>
                        event.target.checked
                          ? [...current, id]
                          : current.filter((value) => value !== id),
                      )
                    }
                  />
                </label>
              );
            })
          )}
        </form>
      </Dialog>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Boxes, MapPin, Package, Pencil, Plus, UserRound, Warehouse as WarehouseIcon } from 'lucide-react';

import { useAuth } from '../context/AuthContext.jsx';
import { useApiResource } from '../hooks/useApiResource.js';
import { ROLES } from '../lib/constants.js';
import { describeError } from '../lib/errors.js';
import { formatNumber } from '../lib/format.js';
import { usersApi, warehousesApi } from '../services/endpoints.js';
import { Badge } from '../components/ui/Badge.jsx';
import { Button } from '../components/ui/Button.jsx';
import { Card } from '../components/ui/Card.jsx';
import { Dialog } from '../components/ui/Dialog.jsx';
import { EmptyState, ErrorState, Skeleton } from '../components/ui/Feedback.jsx';
import { Field, Input, Select } from '../components/ui/Input.jsx';
import { useToast } from '../components/ui/Toast.jsx';

const EMPTY_FORM = { code: '', name: '', location: '', manager_id: '', is_active: true };

export function Warehouses() {
  const { isAdmin } = useAuth();
  const navigate = useNavigate();
  const toast = useToast();

  const warehouses = useApiResource(() => warehousesApi.list({ limit: 100 }), []);
  // Only an Admin may list users, so the manager picker is loaded conditionally.
  const users = useApiResource(() => usersApi.list({ limit: 100 }), [], { skip: !isAdmin });

  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(EMPTY_FORM);
  const [error, setError] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const managers = useMemo(
    () => (users.data ?? []).filter((user) => user.role === ROLES.MANAGER && user.is_active),
    [users.data],
  );

  // A Manager owns at most one warehouse (a database constraint), so a manager
  // already assigned elsewhere is shown but cannot be picked again.
  const takenManagerIds = useMemo(() => {
    const taken = new Map();
    for (const warehouse of warehouses.data ?? []) {
      if (warehouse.manager?.id && warehouse.id !== editing?.id) taken.set(warehouse.manager.id, warehouse.code);
    }
    return taken;
  }, [warehouses.data, editing]);

  function openCreate() {
    setForm(EMPTY_FORM);
    setError(null);
    setEditing({ id: null });
  }

  function openEdit(warehouse) {
    setForm({
      code: warehouse.code,
      name: warehouse.name,
      location: warehouse.location ?? '',
      manager_id: warehouse.manager?.id ? String(warehouse.manager.id) : '',
      is_active: warehouse.is_active,
    });
    setError(null);
    setEditing(warehouse);
  }

  async function handleSubmit(event) {
    event.preventDefault();
    setSubmitting(true);
    setError(null);

    const payload = {
      name: form.name.trim(),
      location: form.location.trim() || null,
      manager_id: form.manager_id ? Number(form.manager_id) : null,
    };

    try {
      if (editing.id) {
        await warehousesApi.update(editing.id, { ...payload, is_active: form.is_active });
        toast.success('Warehouse updated', `${payload.name} has been saved.`);
      } else {
        await warehousesApi.create({ ...payload, code: form.code.trim() });
        toast.success('Warehouse created', `${payload.name} is ready for stock.`);
      }
      setEditing(null);
      warehouses.reload();
    } catch (caught) {
      setError(caught);
    } finally {
      setSubmitting(false);
    }
  }

  const rows = warehouses.data ?? [];

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-base font-semibold tracking-tight">Warehouses</h2>
          <p className="text-xs text-muted-foreground">
            {rows.length} location{rows.length === 1 ? '' : 's'} in your scope.
          </p>
        </div>
        {isAdmin ? (
          <Button onClick={openCreate}>
            <Plus className="h-4 w-4" aria-hidden="true" />
            Add warehouse
          </Button>
        ) : null}
      </div>

      {warehouses.error ? (
        <Card>
          <ErrorState error={warehouses.error} onRetry={warehouses.reload} />
        </Card>
      ) : warehouses.loading ? (
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {Array.from({ length: 3 }).map((_, index) => (
            <Skeleton key={index} className="h-44 w-full" />
          ))}
        </div>
      ) : rows.length === 0 ? (
        <Card>
          <EmptyState
            icon={WarehouseIcon}
            title="No warehouses in your scope"
            description={
              isAdmin
                ? 'Create the first location to start receiving stock.'
                : 'An administrator has not assigned you to a warehouse yet.'
            }
            action={isAdmin ? <Button onClick={openCreate}>Add warehouse</Button> : null}
          />
        </Card>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {rows.map((warehouse) => (
            <Card key={warehouse.id} className="flex flex-col">
              <div className="flex items-start justify-between gap-3 p-4">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <h3 className="truncate text-sm font-semibold">{warehouse.name}</h3>
                    {!warehouse.is_active ? <Badge tone="outline">Inactive</Badge> : null}
                  </div>
                  <p className="mt-0.5 font-mono text-2xs text-muted-foreground">{warehouse.code}</p>
                </div>
                <div className="rounded-md border border-border bg-muted/40 p-1.5">
                  <WarehouseIcon className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
                </div>
              </div>

              <div className="flex flex-1 flex-col gap-3 px-4 pb-4">
                <p className="flex items-start gap-1.5 text-xs text-muted-foreground">
                  <MapPin className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                  {warehouse.location || 'No address recorded'}
                </p>

                {/*
                  The API reports these counts on the list endpoint. There is no
                  capacity field in the schema, so "utilisation" is deliberately
                  absent rather than invented.
                */}
                <div className="grid grid-cols-2 gap-2">
                  <div className="rounded-md border border-border bg-muted/30 p-2">
                    <p className="flex items-center gap-1 text-2xs text-muted-foreground">
                      <Package className="h-3 w-3" aria-hidden="true" />
                      Products
                    </p>
                    <p className="tabular mt-0.5 text-sm font-semibold">
                      {formatNumber(warehouse.counts?.products ?? 0)}
                    </p>
                  </div>
                  <div className="rounded-md border border-border bg-muted/30 p-2">
                    <p className="flex items-center gap-1 text-2xs text-muted-foreground">
                      <Boxes className="h-3 w-3" aria-hidden="true" />
                      Units on hand
                    </p>
                    <p className="tabular mt-0.5 text-sm font-semibold">
                      {formatNumber(warehouse.counts?.units_on_hand ?? 0)}
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-2 rounded-md border border-border p-2">
                  {warehouse.manager ? (
                    <>
                      <span className="flex h-6 w-6 items-center justify-center rounded-full bg-primary/15 text-2xs font-semibold text-primary">
                        {warehouse.manager.name.slice(0, 1)}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate text-xs">{warehouse.manager.name}</p>
                        <p className="truncate text-2xs text-muted-foreground">{warehouse.manager.email}</p>
                      </div>
                    </>
                  ) : (
                    <>
                      <UserRound className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
                      <p className="text-xs text-muted-foreground">No manager assigned</p>
                    </>
                  )}
                </div>
              </div>

              <div className="flex items-center gap-2 border-t border-border p-3">
                <Button
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  // The blueprint's "deep link to inventory filtered by that
                  // warehouse" -- the filter lives in the URL so the view is
                  // shareable and survives a reload.
                  onClick={() => navigate(`/inventory?warehouse_id=${warehouse.id}`)}
                >
                  <Boxes className="h-3.5 w-3.5" aria-hidden="true" />
                  View inventory
                </Button>
                <Button variant="ghost" size="sm" onClick={() => openEdit(warehouse)} disabled={!isAdmin}>
                  <Pencil className="h-3.5 w-3.5" aria-hidden="true" />
                  Edit
                </Button>
              </div>
            </Card>
          ))}
        </div>
      )}

      <Dialog
        open={Boolean(editing)}
        onClose={() => setEditing(null)}
        title={editing?.id ? `Edit ${editing.name}` : 'Add warehouse'}
        description={
          editing?.id
            ? 'Renaming a warehouse does not affect historical orders.'
            : 'A warehouse is a physical location that holds stock.'
        }
        footer={
          <>
            <Button variant="outline" onClick={() => setEditing(null)}>
              Cancel
            </Button>
            <Button type="submit" form="warehouse-form" loading={submitting}>
              {editing?.id ? 'Save changes' : 'Create warehouse'}
            </Button>
          </>
        }
      >
        {error ? (
          <div className="mb-4">
            <ErrorState error={error} />
          </div>
        ) : null}

        <form id="warehouse-form" className="flex flex-col gap-4" onSubmit={handleSubmit}>
          {!editing?.id ? (
            <Field
              label="Code"
              required
              hint="Short identifier used on reports, e.g. WH-NBO."
              error={error?.fieldErrors?.code}
            >
              {(props) => (
                <Input
                  {...props}
                  value={form.code}
                  onChange={(event) => setForm((current) => ({ ...current, code: event.target.value }))}
                  placeholder="WH-ACC"
                  required
                />
              )}
            </Field>
          ) : null}

          <Field label="Name" required error={error?.fieldErrors?.name}>
            {(props) => (
              <Input
                {...props}
                value={form.name}
                onChange={(event) => setForm((current) => ({ ...current, name: event.target.value }))}
                placeholder="Accra Distribution Centre"
                required
              />
            )}
          </Field>

          <Field label="Location" error={error?.fieldErrors?.location}>
            {(props) => (
              <Input
                {...props}
                value={form.location}
                onChange={(event) => setForm((current) => ({ ...current, location: event.target.value }))}
                placeholder="Tema Port Road, Accra, GH"
              />
            )}
          </Field>

          <Field
            label="Manager"
            hint="One manager per warehouse; the database enforces it."
            error={error?.fieldErrors?.manager_id}
          >
            {(props) => (
              <Select
                {...props}
                value={form.manager_id}
                onChange={(event) => setForm((current) => ({ ...current, manager_id: event.target.value }))}
              >
                <option value="">Unassigned</option>
                {managers.map((manager) => {
                  const takenBy = takenManagerIds.get(manager.id);
                  return (
                    <option key={manager.id} value={manager.id} disabled={Boolean(takenBy)}>
                      {manager.name}
                      {takenBy ? ` — already manages ${takenBy}` : ''}
                    </option>
                  );
                })}
              </Select>
            )}
          </Field>

          {editing?.id ? (
            <Field label="Status">
              {(props) => (
                <Select
                  {...props}
                  value={form.is_active ? 'active' : 'inactive'}
                  onChange={(event) =>
                    setForm((current) => ({ ...current, is_active: event.target.value === 'active' }))
                  }
                >
                  <option value="active">Active — can receive stock</option>
                  <option value="inactive">Inactive — retained for history</option>
                </Select>
              )}
            </Field>
          ) : null}
        </form>

        {!editing?.id && managers.length === 0 && !users.loading ? (
          <p className="mt-4 text-2xs text-muted-foreground">
            No active managers exist yet.{' '}
            <Link to="/users" className="focus-ring rounded text-primary hover:underline">
              Create one
            </Link>{' '}
            to assign ownership.
          </p>
        ) : null}
      </Dialog>
    </div>
  );
}
